from fastapi import FastAPI
from fastapi.testclient import TestClient


def make_app():
    app = FastAPI()
    counter = {"n": 0}

    @app.post("/count")
    def count():
        counter["n"] += 1
        return {"n": counter["n"]}

    return app


def hit(client):
    return client.post("/count").json()["n"]

from fastapi import Depends, FastAPI
from fastapi.testclient import TestClient

app = FastAPI()


def get_rate():
    return 4.3          # в жизни здесь запрос к банку


@app.get("/convert/{eur}")
def convert(eur: float, rate: float = Depends(get_rate)):
    return {"pln": round(eur * rate, 2)}
